 26	/**
 27	 * A builder for constructing instances of {@link MutableGraph} or {@link ImmutableGraph} with
 28	 * user-defined properties.
 29	 *
 30	 * <p>A {@code Graph} built by this class has the following default properties:
 31	 *
 32	 * <ul>
 33	 *   <li>does not allow self-loops
 34	 *   <li>orders {@link Graph#nodes()} in the order in which the elements were added (insertion
 35	 *       order)
 36	 * </ul>
 37	 *
 38	 * <p>{@code Graph}s built by this class also guarantee that each collection-returning accessor
 39	 * returns a <b>(live) unmodifiable view</b>; see <a
 40	 * href="https://github.com/google/guava/wiki/GraphsExplained#accessor-behavior">the external
 41	 * documentation</a> for details.
 42	 *
 43	 * <p>Examples of use:
 44	 *
 45	 * {@snippet :
 46	 * // Building a mutable graph
 47	 * MutableGraph<String> graph = GraphBuilder.undirected().allowsSelfLoops(true).build();
 48	 * graph.putEdge("bread", "bread");
 49	 * graph.putEdge("chocolate", "peanut butter");
 50	 * graph.putEdge("peanut butter", "jelly");
 51	 *
 52	 * // Building an immutable graph
 53	 * ImmutableGraph<String> immutableGraph =
 54	 *     GraphBuilder.undirected()
 55	 *         .allowsSelfLoops(true)
 56	 *         .<String>immutable()
 57	 *         .putEdge("bread", "bread")
 58	 *         .putEdge("chocolate", "peanut butter")
 59	 *         .putEdge("peanut butter", "jelly")
 60	 *         .build();
 61	 * }
 62	 *
 63	 * @author James Sexton
 64	 * @author Joshua O'Madadhain
 65	 * @param <N> The most general node type this builder will support. This is normally {@code Object}
 66	 *     unless it is constrained by using a method like {@link #nodeOrder}, or the builder is
 67	 *     constructed based on an existing {@code Graph} using {@link #from(Graph)}.
 68	 * @since 20.0
 69	 */
 70	@DoNotMock
 71	public final class GraphBuilder<N> extends AbstractGraphBuilder<N> {
 72	
 73	  /** Creates a new instance with the specified edge directionality. */
 74	  private GraphBuilder(boolean directed) {
 75	    super(directed);
 76	  }
 77	
 78	  /** Returns a {@link GraphBuilder} for building directed graphs. */
 79	  public static GraphBuilder<Object> directed() {
 80	    return new GraphBuilder<>(true);
 81	  }
 82	
 83	  /** Returns a {@link GraphBuilder} for building undirected graphs. */
 84	  public static GraphBuilder<Object> undirected() {
 85	    return new GraphBuilder<>(false);
 86	  }
 87	
 88	  /**
 89	   * Returns a {@link GraphBuilder} initialized with all properties queryable from {@code graph}.
 90	   *
 91	   * <p>The "queryable" properties are those that are exposed through the {@link Graph} interface,
 92	   * such as {@link Graph#isDirected()}. Other properties, such as {@link #expectedNodeCount(int)},
 93	   * are not set in the new builder.
 94	   */
 95	  public static <N> GraphBuilder<N> from(Graph<N> graph) {
 96	    return new GraphBuilder<N>(graph.isDirected())
 97	        .allowsSelfLoops(graph.allowsSelfLoops())
 98	        .nodeOrder(graph.nodeOrder())
 99	        .incidentEdgeOrder(graph.incidentEdgeOrder());
100	  }
101	
102	  /**
103	   * Returns an {@link ImmutableGraph.Builder} with the properties of this {@link GraphBuilder}.
104	   *
105	   * <p>The returned builder can be used for populating an {@link ImmutableGraph}.
106	   *
107	   * <p>Note that the returned builder will always have {@link #incidentEdgeOrder} set to {@link
108	   * ElementOrder#stable()}, regardless of the value that was set in this builder.
109	   *
110	   * @since 28.0
111	   */
112	  public <N1 extends N> ImmutableGraph.Builder<N1> immutable() {
113	    GraphBuilder<N1> castBuilder = cast();
114	    return new ImmutableGraph.Builder<>(castBuilder);
115	  }
116	
117	  /**
118	   * Specifies whether the graph will allow self-loops (edges that connect a node to itself).
119	   * Attempting to add a self-loop to a graph that does not allow them will throw an {@link
120	   * UnsupportedOperationException}.
121	   *
122	   * <p>The default value is {@code false}.
123	   */
124	  @CanIgnoreReturnValue
125	  public GraphBuilder<N> allowsSelfLoops(boolean allowsSelfLoops) {
126	    this.allowsSelfLoops = allowsSelfLoops;
127	    return this;
128	  }
129	
130	  /**
131	   * Specifies the expected number of nodes in the graph.
132	   *
133	   * @throws IllegalArgumentException if {@code expectedNodeCount} is negative
134	   */
135	  @CanIgnoreReturnValue
136	  public GraphBuilder<N> expectedNodeCount(int expectedNodeCount) {
137	    this.expectedNodeCount = checkNonNegative(expectedNodeCount);
138	    return this;
139	  }
140	
141	  /**
142	   * Specifies the order of iteration for the elements of {@link Graph#nodes()}.
143	   *
144	   * <p>The default value is {@link ElementOrder#insertion() insertion order}.
145	   */
146	  public <N1 extends N> GraphBuilder<N1> nodeOrder(ElementOrder<N1> nodeOrder) {
147	    GraphBuilder<N1> newBuilder = cast();
148	    newBuilder.nodeOrder = checkNotNull(nodeOrder);
149	    return newBuilder;
150	  }
151	
152	  /**
153	   * Specifies the order of iteration for the elements of {@link Graph#edges()}, {@link
154	   * Graph#adjacentNodes(Object)}, {@link Graph#predecessors(Object)}, {@link
155	   * Graph#successors(Object)} and {@link Graph#incidentEdges(Object)}.
156	   *
157	   * <p>The default value is {@link ElementOrder#unordered() unordered} for mutable graphs. For
158	   * immutable graphs, this value is ignored; they always have a {@link ElementOrder#stable()
159	   * stable} order.
160	   *
161	   * @throws IllegalArgumentException if {@code incidentEdgeOrder} is not either {@code
162	   *     ElementOrder.unordered()} or {@code ElementOrder.stable()}.
163	   * @since 29.0
164	   */
165	  public <N1 extends N> GraphBuilder<N1> incidentEdgeOrder(ElementOrder<N1> incidentEdgeOrder) {
166	    checkArgument(
167	        incidentEdgeOrder.type() == ElementOrder.Type.UNORDERED
168	            || incidentEdgeOrder.type() == ElementOrder.Type.STABLE,
169	        "The given elementOrder (%s) is unsupported. incidentEdgeOrder() only supports"
170	            + " ElementOrder.unordered() and ElementOrder.stable().",
171	        incidentEdgeOrder);
172	    GraphBuilder<N1> newBuilder = cast();
173	    newBuilder.incidentEdgeOrder = checkNotNull(incidentEdgeOrder);
174	    return newBuilder;
175	  }
176	
177	  /** Returns an empty {@link MutableGraph} with the properties of this {@link GraphBuilder}. */
178	  public <N1 extends N> MutableGraph<N1> build() {
179	    return new StandardMutableGraph<>(this);
180	  }
181	
182	  GraphBuilder<N> copy() {
183	    GraphBuilder<N> newBuilder = new GraphBuilder<>(directed);
184	    newBuilder.allowsSelfLoops = allowsSelfLoops;
185	    newBuilder.nodeOrder = nodeOrder;
186	    newBuilder.expectedNodeCount = expectedNodeCount;
187	    newBuilder.incidentEdgeOrder = incidentEdgeOrder;
188	    return newBuilder;
189	  }
190	
191	  @SuppressWarnings("unchecked")
192	  private <N1 extends N> GraphBuilder<N1> cast() {
193	    return (GraphBuilder<N1>) this;
194	  }
195	}

